create extension if not exists pgcrypto;
create table public.resources (id uuid primary key default gen_random_uuid(),type text not null check (type in ('link','note')),title text not null check (char_length(title) between 1 and 100),url text,body text check (body is null or char_length(body)<=2000),subject text not null check (char_length(subject) between 1 and 60),semester int not null check (semester between 1 and 8),tags text[] not null default '{}' check (cardinality(tags)<=6),author text check (author is null or char_length(author)<=50),upvotes int not null default 0 check (upvotes>=0),link_status text not null default 'unknown' check (link_status in ('unknown','ok','broken','unreachable')),owner_token uuid not null,created_at timestamptz not null default now(),check ((type='link' and url is not null) or (type='note' and body is not null)));
alter table public.resources enable row level security;create policy "public read" on public.resources for select to anon using(true);create policy "public insert" on public.resources for insert to anon with check(true);revoke all on public.resources from anon,authenticated;grant select(id,type,title,url,body,subject,semester,tags,author,upvotes,link_status,created_at) on public.resources to anon;grant insert(type,title,url,body,subject,semester,tags,author,owner_token) on public.resources to anon;
create or replace function public.increment_upvote(row_id uuid,delta int) returns int language plpgsql security definer set search_path=public as $$declare new_count int;begin update public.resources set upvotes=greatest(0,upvotes+least(1,greatest(-1,delta))) where id=row_id returning upvotes into new_count;return new_count;end$$;
create or replace function public.update_own_resource(row_id uuid,token uuid,p_title text,p_url text,p_body text,p_subject text,p_semester int,p_tags text[],p_author text) returns boolean language plpgsql security definer set search_path=public as $$begin update public.resources set title=p_title,url=p_url,body=p_body,subject=p_subject,semester=p_semester,tags=p_tags,author=p_author where id=row_id and owner_token=token;return found;end$$;
create or replace function public.delete_own_resource(row_id uuid,token uuid) returns boolean language plpgsql security definer set search_path=public as $$begin delete from public.resources where id=row_id and owner_token=token;return found;end$$;
create or replace function public.set_link_status(row_id uuid,status text) returns void language sql security definer set search_path=public as $$update public.resources set link_status=status where id=row_id$$;
grant execute on function public.increment_upvote(uuid,int) to anon;grant execute on function public.update_own_resource(uuid,uuid,text,text,text,text,int,text[],text) to anon;grant execute on function public.delete_own_resource(uuid,uuid) to anon;grant execute on function public.set_link_status(uuid,text) to anon;
